// 1. 工厂模式 - BeanFactory
public interface BeanFactory {
    Object getBean(String name) throws BeansException;
    <T> T getBean(Class<T> requiredType) throws BeansException;
}
public interface FactoryBean<T> {
    T getObject() throws Exception;
    Class<?> getObjectType();
    boolean isSingleton();
}

// 2. 代理模式 - AOP
// JDK动态代理
public class JdkDynamicAopProxy implements InvocationHandler {
    @Override
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        // 执行拦截器链
        return new ReflectiveMethodInvocation(target, method, args, interceptors).proceed();
    }
}

// 3. 观察者模式 - ApplicationEvent
public class ApplicationEventPublisher {
    public void publishEvent(ApplicationEvent event) {
        // 通知所有监听器
    }
}
@Component
public class MyListener implements ApplicationListener<ApplicationEvent> {
    @Override
    public void onApplicationEvent(ApplicationEvent event) {
        // 处理事件
    }
}

// 4. 模板方法 - JdbcTemplate
public class JdbcTemplate {
    public <T> T execute(PreparedStatementCreator psc, PreparedStatementCallback<T> action) {
        Connection con = DataSourceUtils.getConnection(dataSource);
        try {
            PreparedStatement ps = psc.createPreparedStatement(con);
            return action.doInPreparedStatement(ps);
        } finally {
            DataSourceUtils.releaseConnection(con, dataSource);
        }
    }
}

// 5. 策略模式 - Resource
public interface Resource extends InputStreamSource {
    boolean exists();
    URL getURL() throws IOException;
    File getFile() throws IOException;
}
// 不同策略实现
class ClassPathResource implements Resource { ... }
class FileSystemResource implements Resource { ... }
class UrlResource implements Resource { ... }

// 6. 单例模式 - Bean作用域
@Scope("singleton")  // 默认
@Component
